SELECT COALESCE(group_concat(word_id), '') FROM (SELECT a.word_id AS word_id, a.direction AS direction, a.id AS last_wrong_id, a.answer AS last_answer, a.at AS last_at FROM (SELECT word_id, direction, mid, SUM(CASE WHEN correct = 1 AND hinted = 0 AND id > mid THEN 1 ELSE 0 END) AS good FROM (SELECT id, word_id, direction, correct, hinted, MAX(CASE WHEN correct = 0 THEN id END) OVER (PARTITION BY word_id, direction) AS mid FROM dictation_attempt WHERE learner = :learner AND subject_id = CAST(:subject_id AS INTEGER)) WHERE mid IS NOT NULL GROUP BY word_id, direction, mid) g JOIN dictation_attempt a ON a.id = g.mid WHERE g.good < 2 ORDER BY a.id DESC) WHERE direction = :direction
